package com.app.nuri.unstuck

/** Part B (phone, #52–87) and Part C (Show Nuri, #88–98) catalog data. */
object HelperCatalogDataB {
    val all: List<HelperDef> = listOf(
        // ── B1 · Home screen & navigation ────────────────────────────
        HelperDef(52, "B1", "My app is gone — the picture I tap isn't there", HelperMode.GUIDED, triggers = listOf("app is gone", "my app disappeared", "picture i tap is gone"),
            steps = listOf("Apps slide around when the screen gets pressed in a pocket — it's usually moved, not deleted. Swipe up from the bottom to open the full app list and look for it there.", "Found it? To put it back: press and hold its picture, then slide it to your home screen.", "If it isn't in the list at all, it may have been deleted — that has its own fix ('I deleted the app'), and the store remembers you had it.")),
        HelperDef(53, "B1", "I pressed something and everything is shaking / minus signs", HelperMode.GUIDED, triggers = listOf("icons shaking", "everything is moving", "minus signs", "apps are wiggling"),
            steps = listOf("Nothing is broken and nothing is deleted. Your phone thinks you want to rearrange the pictures — that's all this is.", "Press the back button once, or tap an empty patch of screen. Did the shaking stop?", "While it shakes, a minus tap can remove a shortcut — never your photos or numbers — and shortcuts come back. Still, best to just stop the shaking.")),
        HelperDef(54, "B1", "The buttons at the bottom are gone / swiping does strange things", HelperMode.GUIDED, triggers = listOf("buttons at the bottom gone", "no buttons", "swiping strange", "navigation changed"),
            steps = listOf("Your phone switched to swiping instead of buttons — an update or an accident can do that. The buttons can come back.", "The one swipe you need today: swipe up from the very bottom to go home. Let's practice it twice.", "If you want the buttons back for good, that's a settings walk we can do together slowly — or a good caregiver job. Your tap does each step; navigation is your preference, never something I switch silently.")),
        HelperDef(55, "B1", "This phone looks completely different today", HelperMode.GUIDED, triggers = listOf("phone looks different", "phone changed overnight", "everything looks different on my phone"),
            steps = listOf("Your phone updated itself in the night. Nothing of yours is gone — the furniture moved, that's all.", "Let's rebuild the three things you use most, one at a time, opening each together.", "And one thing never changes: my voice and the way you talk to me. Updates can't move me.")),
        // ── B2 · In-call & pocket problems ───────────────────────────
        HelperDef(56, "B2", "Pocket dials — \"it called Karen by itself, again\"", HelperMode.GUIDED, triggers = listOf("pocket dial", "it called by itself", "phone dialed itself"),
            steps = listOf("No blame — the screen woke in your pocket and your leg did the tapping. It happens to everyone.", "The one habit that stops most of it: click the power button before the phone goes in a pocket, and check together now that the screen is black.", "If pocket emergency calls keep happening, tell your caregiver — a case with a cover, or a different pocket, is a physical fix a person helps with.")),
        HelperDef(57, "B2", "Mid-call accidents — mute / hold / speaker / \"they're gone\"", HelperMode.AUTO_CHECK, checkKey = CheckKey.SOUND, triggers = listOf("call went silent", "they can't hear me", "i pressed mute", "call disappeared mid call"),
            steps = listOf("First, one question: can they not hear you, or can you not hear them?", "If they can't hear you: look for the microphone picture with a line through it on the call screen — tap it once. That's the mute.", "If you can't hear them, sound may be going somewhere else — a speaker or hearing device in another room can grab a call. I checked the sound route first.", "If the call seems gone but a timer is still running, it's on hold — tap the pause picture once. And remember: you can't break a phone call by tapping. Worst case, we call back.")),
        HelperDef(58, "B2", "The call just ended and I don't know why — did I hang up on her?", HelperMode.GUIDED, triggers = listOf("call just ended", "did i hang up", "call dropped"),
            steps = listOf("Settle the worry first: calls drop on their own all the time — signal, battery, a cheek tap. We'll never know which, and it doesn't matter.", "Let's just call her back. She'll be glad, and 'the phone dropped us' is a complete explanation.")),
        // ── B3 · Messages ────────────────────────────────────────────
        HelperDef(59, "B3", "I sent it in the wrong app (green / blue / WhatsApp)", HelperMode.GUIDED, triggers = listOf("wrong app message", "sent in whatsapp", "wrong messaging app"),
            steps = listOf("It still went to the same person — these apps are just different doors into the same house.", "The cue that matters: the app you open is the door; the person's name at the top is who hears it.", "Let's agree your household default — family in one app, everyone else in texts — and I'll keep it in your anchors so my answers stay consistent.")),
        HelperDef(60, "B3", "I sent that to the wrong person", HelperMode.GUIDED, triggers = listOf("sent to the wrong person", "wrong person message"),
            steps = listOf("Speed first, shame never — these can often be undone. Press and hold the message, right now, and look for Delete or Unsend.", "If it can't be unsent, one follow-up fixes most cases: 'Sorry — that was meant for someone else, please ignore it.'", "If the message had money or account details in it, that's a same-day caregiver conversation — I never handle the credentials, but a person should know today.")),
        HelperDef(61, "B3", "My photo won't send / the message failed with a red mark", HelperMode.AUTO_CHECK, checkKey = CheckKey.CONNECTIVITY, triggers = listOf("photo won't send", "message failed", "red mark message", "message won't send"),
            steps = listOf("I checked the connection pieces first — mobile data off is the number-one cause.", "Let's retry once together.", "If it's a long video: the phone post has a size limit, like an envelope. Send the photo instead, a shorter clip, or wait for home Wi-Fi.")),
        HelperDef(62, "B3", "Did she read it? What do the little ticks / 'typing\u2026' mean?", HelperMode.GUIDED, triggers = listOf("did she read it", "what do the ticks mean", "blue ticks", "typing mean"),
            steps = listOf("The marks differ by app, so first: which app are you looking at? In WhatsApp, two blue ticks mean she has seen it. One grey tick means sent; two grey, delivered.", "Now the important part: 'seen' doesn't mean she's ignoring you. It means the phone showed it — people see messages in the car and answer at home.")),
        HelperDef(63, "B3", "Spam texts — bank texts, prize texts, a wrong-number 'hi'", HelperMode.GUIDED, checkKey = CheckKey.SCAM_TEXT, triggers = listOf("spam text", "bank texted me", "prize text", "wrong number hi"),
            steps = listOf("Don't tap and don't answer — answering tells them the number is alive.", "Let's block it together, once, slowly: press and hold the message, then Block. Then we delete it.", "One pattern to know: a 'wrong number' text that turns into daily chats and then asks about money is a known trick. Real wrong numbers say sorry and stop.", "If you tapped a link or entered anything, we go to your caregiver and the bank right away.")),
        // ── B4 · Contacts ────────────────────────────────────────────
        HelperDef(64, "B4", "She's in my phone twice / three times — which one is real?", HelperMode.GUIDED, triggers = listOf("in my phone twice", "duplicate contacts", "two contacts same person"),
            steps = listOf("Let's compare them aloud: the phone numbers are the tell. One often ends in a number you recognize as her new one.", "Today's need comes first: we call the right one now, with no editing at all.", "The tidy-up — merging them — is a guided job we can do slowly, or park: duplicates are untidy, not dangerous, and I will always pick the right one for you.")),
        HelperDef(65, "B4", "When the doctor calls it just shows a number — no name", HelperMode.GUIDED, triggers = listOf("just shows a number", "no name on call", "doctor calls no name"),
            steps = listOf("The phone only knows names for numbers that were saved. This one was never saved — that's the whole cause.", "Let's save it once: open Recents, tap the number, tap Create contact, and we'll say the name together — I'll spell it with you.", "While we're here, the other numbers that matter — pharmacy, clinic, family — are worth the same two minutes, offered, not imposed.")),
        HelperDef(66, "B4", "I can't find a person in my contacts / the list is full of strangers", HelperMode.GUIDED, triggers = listOf("can't find in contacts", "contacts full of strangers", "find a person"),
            steps = listOf("Tell me the name and I'll search the variants — first name only, a 'Dr.' in front, an old spelling. Finding, not scrolling, is the point.", "The strangers usually came from an old email address book. They're harmless. Hiding that book is possible, but it touches account settings, so that's a caregiver job if you want it done.")),
        // ── B5 · Notifications ───────────────────────────────────────
        HelperDef(67, "B5", "Notification flood — beeping all day / flashlight left on / pocket chaos", HelperMode.AUTO_CHECK, checkKey = CheckKey.FLASHLIGHT, triggers = listOf("beeps all day", "too many notifications", "flashlight is on", "phone keeps beeping"),
            steps = listOf("I checked the flashlight first — if it was on, I've turned it off and I'll say so.", "The flood is usually two or three chatty apps. One tidy fixes most of it: press and hold one of the junk notifications, then tap 'Turn off notifications' — your tap, because which apps may speak is your preference.", "Any time you want, ask me 'what did I miss?' and I'll read the important ones and skip the noise.")),
        HelperDef(68, "B5", "I swiped it away — what was that reminder? It's gone", HelperMode.GUIDED, triggers = listOf("swiped it away", "what was that reminder", "notification gone"),
            steps = listOf("No scolding — swiping is what the phone teaches everyone to do.", "If it was one of my reminders, I keep my own record and can read it back: nothing of mine is lost by a swipe.", "If it came from another app and the phone kept no history, I'll say so honestly — and we can turn notification history on together, one setting, so next time it's retrievable.")),
        HelperDef(69, "B5", "Nothing ever beeps anymore — I missed Karen's message", HelperMode.AUTO_CHECK, checkKey = CheckKey.DND, triggers = listOf("nothing beeps", "missed a message", "phone silent", "no notifications anymore"),
            steps = listOf("I checked the global pieces first — Do Not Disturb and volume. If Do Not Disturb was on and I could switch it off, I've done it and I'll say so.", "The sneaky cause: the conversation itself was muted. Open the chat and look for a little crossed-out bell — that's it.", "Let's prove it: I'll describe a test — message yourself from the family chat or ask me again in a minute — and you should hear it beep.")),
        // ── B6 · Sound, display & accessibility drift ────────────────
        HelperDef(70, "B6", "TalkBack turned on by accident — phone talks everything, taps don't work", HelperMode.AUTO_CHECK, checkKey = CheckKey.TALKBACK, triggers = listOf("phone talks everything", "talkback", "screen reader on", "phone reads my screen"),
            steps = listOf("First, the fastest way out: hold BOTH volume buttons together for three seconds. That turns the reading voice off on most phones.", "Still on? Then we use its own rules, calmly: tap something ONCE to hear it, then DOUBLE-tap to choose it. Scrolling takes two fingers.", "With those rules: open Settings (tap once, double-tap), then Accessibility, then TalkBack, and switch it off — one screen at a time, I'm with you.", "If we can't get out after that, tap 'I'm stuck' — we'll get a person on the phone with you. Your voice still works the whole time; that's the lifeline.")),
        HelperDef(71, "B6", "The words are tiny today / everything is HUGE and cut off", HelperMode.AUTO_CHECK, checkKey = CheckKey.TEXT_SIZE, triggers = listOf("words are tiny", "everything is huge", "text too big", "screen zoomed"),
            steps = listOf("If the screen is simply zoomed in, a triple-tap — three quick taps — usually un-zooms it. Try that first.", "Otherwise: Settings, then Display, then Font size, and slide back to your usual — the second-biggest is many people's. In Nuri itself the words never go below easy-to-read; that part can't drift.", "If the words are already at your usual size but still unreadable in one app, that app has its own zoom — or, if your vision changed suddenly, that's not a settings matter: we tell your caregiver today.")),
        HelperDef(72, "B6", "Screen goes black while reading / spins sideways / dark-and-yellow at night", HelperMode.GUIDED, triggers = listOf("screen goes black", "screen spins", "screen sideways", "screen yellow at night"),
            steps = listOf("Going black while reading is the screen's rest timer — 30 seconds is too short for reading. Settings, Display, Screen timeout: give it several minutes.", "Spinning sideways is auto-rotate. If you read lying down, locking it upright is the fix: swipe down from the top and tap the rotate picture to lock it.", "Dark-and-yellow at night is the night light doing its job on purpose — it is not damage. Keep it if your eyes like it; it can be softened in the same Display settings.")),
        // ── B7 · Battery, charging & connectivity ─────────────────────
        HelperDef(73, "B7", "It's plugged in but it isn't charging", HelperMode.AUTO_CHECK, checkKey = CheckKey.BATTERY, triggers = listOf("isn't charging", "plugged in not charging", "won't charge"),
            steps = listOf("I checked the battery first — now the order matters, one change at a time. Is the wall socket alive? Try the lamp on it, or move the charger to a socket you know works.", "Next: push the charger brick firmly into the socket, and the cable firmly into the brick. Watch for the little lightning bolt with me.", "Swap the cable end-for-end, or try your other cable if you have one.", "Look into the phone's charging hole with a light: pocket fluff packs in there. A dry wooden toothpick, phone off, gently — never metal, never digging. If it won't come, we stop.", "One more possibility: some phones stop at 80 or 85 percent on purpose to protect the battery. If yours says that, it is full — for it.", "If the battery is hot, swollen, or a cable smells burnt — stop charging and we get a person. That's safety, not troubleshooting.")),
        HelperDef(74, "B7", "\"Emergency calls only\" / no service / a triangle with \"!\"", HelperMode.AUTO_CHECK, checkKey = CheckKey.CONNECTIVITY, triggers = listOf("emergency calls only", "no service", "no signal triangle"),
            steps = listOf("I checked Airplane Mode and data first — if Airplane Mode was on and I could switch it off, I've done it; watch for the signal bars coming back with me.", "If the phone stopped its data at a limit: that's the phone protecting you from a surprise bill. Wi-Fi still works, and raising the limit is a caregiver conversation, not a phone fix.", "On hotel or café Wi-Fi: those ask for one tap on their own page before the internet works — nothing to pay, nothing to sign.", "No service for hours at home while a neighbor's works? That's the carrier — a caregiver call. If you need someone right now, a landline or a neighbor's phone is the plan while we sort it.")),
        HelperDef(75, "B7", "Bluetooth is playing my call in the car / a speaker in another room", HelperMode.AUTO_CHECK, checkKey = CheckKey.SOUND, triggers = listOf("call in the car", "sound in another room", "bluetooth wrong device", "call playing elsewhere"),
            steps = listOf("I checked where the sound is going first. The classic cause: the car was still awake in the driveway and grabbed the call.", "On the call screen, tap the sound button and choose where you want it — your hearing aids first, if you wear them; that's the rule we set at setup.", "If one device keeps stealing your calls, we can forget it together — that's a settings change, so it's your tap, guided — or park it for your caregiver.")),
        // ── B8 · Apps in depth ────────────────────────────────────────
        HelperDef(76, "B8", "I deleted the app by accident — can I get it back?", HelperMode.GUIDED, triggers = listOf("deleted the app", "deleted app by accident", "get my app back"),
            steps = listOf("Deleting the picture-book doesn't burn the book: the store remembers you had it, and putting it back is free.", "Open the Play Store, tap your picture at the top, then Manage apps, then look in 'Not installed' — it's there. Tap Install. Your taps, because the store is account territory.", "Honest expectations: things kept online come back after sign-in; some apps' private notes may not. If a sign-in wall appears, we stop and ask — passwords are never mine to touch.")),
        HelperDef(77, "B8", "It stopped — everything stopped (frozen app vs frozen phone)", HelperMode.GUIDED, triggers = listOf("everything stopped", "app frozen", "phone frozen", "it stopped working"),
            steps = listOf("Key insight first: you and I are talking, so your phone is alive. It's the one app that's stuck, like a frozen picture.", "The one-app fix: tap the square button at the bottom, swipe the stuck app away, then open it fresh. Wait with me while it loads.", "Only if the screen itself won't answer at all: hold the power button and tap Restart. Nothing is lost by restarting — the screen goes black for about a minute, and that's normal.")),
        HelperDef(78, "B8", "There's an app on here I never put there", HelperMode.GUIDED, triggers = listOf("app i never put there", "unknown app", "strange app on my phone", "mystery app"),
            steps = listOf("Sort by evidence, not fear: most mystery apps came with the phone from the maker or carrier. We check where it came from in its app info — the store it lists tells the story.", "A genuinely foreign one — recent, installed from outside the store, asking to read your messages or control the phone — we do NOT open. We remove it together if a normal uninstall works.", "And the standing rule: if it says 'your phone is infected, call this number' — that message IS the scam. Nobody legitimate talks that way.")),
        HelperDef(79, "B8", "It wants me to sign in again / it forgot me / it can't see my photos", HelperMode.GUIDED, triggers = listOf("sign in again", "it forgot me", "app can't see my photos", "permission gone"),
            steps = listOf("One app asking again is normal — sessions expire, especially after updates. Everything at once is bigger, and that's a caregiver job.", "If an app 'can't see your photos': phones take back permissions from apps that sleep for months. That's protection, not breakage. We restore just that one together: Settings, Apps, the app, Permissions, Allow — your taps.", "At any password screen, we stop. Your family's password process is the way, with your caregiver beside you — never me, never guessing.")),
        // ── B9 · Camera & photos ─────────────────────────────────────
        HelperDef(80, "B9", "The camera shows ME / it's blurry / the screen is black", HelperMode.GUIDED, triggers = listOf("camera shows me", "camera blurry", "camera black screen", "selfie camera"),
            steps = listOf("If you see your own face, the camera is pointing at you: tap the two circling arrows — that's the turn-around button — and we'll do a smile test.", "Blurry, in order: wipe the little lens with a soft cloth — fingerprints are the number-one cause. Then tap the face or thing on screen to focus. Then hold still for one breath.", "Black screen: another app may still be holding the camera. Swipe that app away — the square button — and open the camera fresh. And kindly said: check no case flap or finger is over the lens; it happens to every photographer.")),
        HelperDef(81, "B9", "My photos are gone", HelperMode.GUIDED, triggers = listOf("photos are gone", "my photos disappeared", "photos missing"),
            steps = listOf("Photos live in two houses on this phone — the gallery and Google Photos — and 'gone' usually means we're in the wrong house. Let's check the other one first.", "Next, the trash in both apps: deleted photos sit there for a month or two and come back with one tap.", "If they're older than the trash keeps and there's no backup, I'll say so honestly and fast — recovery is a person's job, and false hope is worse than a straight answer.")),
        HelperDef(82, "B9", "QR codes — \"point my camera at the square\"", HelperMode.GUIDED, triggers = listOf("qr code", "point camera at square", "scan the square", "scan this code"),
            steps = listOf("Point the camera at the square — and before tapping anything, we read the address that pops up, together, out loud. That preview line is the whole protection.", "A menu code names the restaurant; a Wi-Fi code names the network. A payment code naming a stranger — or a sticker stuck over another code on a meter or table — means stop.", "Money never moves by QR this way. The standing answer is: not this way, not today — money goes through the ways your caregiver set up. We can always ask them instead.")),
        // ── B10 · Alarms, calendar & reminders ───────────────────────
        HelperDef(83, "B10", "My alarm didn't go off", HelperMode.AUTO_CHECK, checkKey = CheckKey.ALARM, triggers = listOf("alarm didn't go off", "alarm didn't ring", "missed my alarm"),
            steps = listOf("I check three things first: the alarm time itself, the alarm's own volume, and whether Do Not Disturb let it through.", "The number-one cause, said with zero mockery — it defeats everyone: the alarm is set for PM instead of AM. Let's read what yours actually says, fix it together, and then test-fire it in one minute so you hear it ring.", "If Do Not Disturb ate it, we restore the alarms-through exception together and test again.", "For days that really matter, there's a belt-and-braces option: a second alarm from me, tied to your routine. Your choice, always.")),
        HelperDef(84, "B10", "The appointment vanished / it's on the wrong day", HelperMode.GUIDED, triggers = listOf("appointment vanished", "appointment wrong day", "appointment not on my phone"),
            steps = listOf("Appointments live in more than one calendar on a phone — 'vanished' usually means 'in the other calendar'. Let's search by the clinic's name together.", "If you have the paper appointment card, show me with 'Show Nuri' — we'll read the day spelled out.", "If it truly isn't there, we re-enter it together from the card, and I read it back to confirm. If the letter and the phone disagree, the letter wins and we call the clinic to be sure.")),
        // ── B11 · Typing & voice input ───────────────────────────────
        HelperDef(85, "B11", "The keyboard changed — mic button gone / it types by itself / it changes my words", HelperMode.GUIDED, triggers = listOf("keyboard changed", "microphone button gone", "keyboard typing by itself", "autocorrect changes my words"),
            steps = listOf("One fix at a time, biggest first: get the right keyboard back. There's a small keyboard-switcher key near the space bar — tap it and choose your usual one.", "The microphone key hides in different spots: often a long press on the comma or the space bar, or a key above the letters. We'll find yours together, slowly.", "Autocorrect changing your words: before sending, the suggestions above the keyboard include your exact word on the left — tapping it keeps your word. Turning autocorrect off entirely is also fine — your tap, your preference.", "One warning that matters: if the keyboard itself is one you never chose, that's not a preference — keyboards see everything typed. That one is a same-day caregiver conversation.")),
        HelperDef(86, "B11", "It doesn't understand me when I talk to it", HelperMode.GUIDED, triggers = listOf("doesn't understand me", "dictation doesn't work", "it can't hear me", "speech not working"),
            steps = listOf("Most 'it can't hear me' is plumbing, not your voice: the sound may be routed to hearing aids or a car. I checked the route first.", "What genuinely helps, framed honestly as the phone's limits: shorter sentences, a small pause between them, phone a hand's-width from your mouth. We'll try it on one fun sentence — never a drill, never a score.", "And the standing fallback, always available: talk to me instead, and I'll write it down as a note that can be sent. Your words get there either way.")),
        // ── B12 · Accidental emergency ───────────────────────────────
        HelperDef(87, "B12", "I called 911 by accident / SOS went off", HelperMode.ESCALATE, triggers = listOf("called 911 by accident", "accidental 911", "sos went off", "accidental sos"),
            steps = listOf("If the call is happening now: stay on the phone and say, 'I'm sorry, I dialed by accident, I'm safe, nobody is hurt.' Then let THEM hang up. Hanging up silently is what sends a callback or a visit.", "If it already ended, expect a callback and use the same sentence — dispatchers hear it every day and they're kind about it.", "Afterwards, let's de-arm it: accidental SOS usually comes from pressing the side button many times, or squeezing the phone. Turning that trigger down is a caregiver-level setup change — a safety feature is never quietly removed in a confused moment, so we ask together.")),
        // ── Part C · Show Nuri ───────────────────────────────────────
        HelperDef(88, "C", "Read this letter to me (Show Nuri)", HelperMode.GUIDED, triggers = listOf("read this letter to me", "show nuri letter"),
            steps = listOf("Tap 'Show Nuri', lay the letter flat in good light, and take the photo. I'll read it aloud at your pace.", "Then the plain summary and three questions: Who sent it? What do they want? Is there a date?", "If it asks for money or personal information from someone unidentified, we stop and treat it as a scam warning first.")),
        HelperDef(89, "C", "Read my pill bottle — and what is this loose pill? (Show Nuri)", HelperMode.GUIDED, triggers = listOf("read my pill bottle", "what is this loose pill", "pill bottle label"),
            steps = listOf("The bottle first: tap 'Show Nuri' and photo the label. I'll read the name and the directions exactly as written, and the refill line. Reading a label is always allowed — and it catches pharmacy mix-ups.", "A loose pill is different, and here I stop: a loose pill can't be named safely from a picture, and guessing with medicine is how people get hurt.", "It goes back in the drawer until we ask the pharmacy — or we ask your caregiver. That choice is yours; the not-guessing is not negotiable.")),
        HelperDef(90, "C", "Is this still good to eat? (Show Nuri)", HelperMode.GUIDED, triggers = listOf("is this still good to eat", "food date", "expiry date"),
            steps = listOf("Tap 'Show Nuri' and photo the date on the package. First I'll tell you which kind of date it is: 'use by' is the safety line; 'best by' is about taste. They are not the same.", "The rule that protects you: a passed use-by date, a broken seal, or food you can't account for means — when in doubt, throw it out. No meal is worth a sick night.", "I'll read dates and labels, but I never declare food safe to eat. That call stays conservative, always.")),
        HelperDef(91, "C", "Which button do I press? What does this display say? (Show Nuri)", HelperMode.GUIDED, triggers = listOf("which button", "what does this display say", "error code photo", "remote control help"),
            steps = listOf("Tap 'Show Nuri' and photo the remote or the display. I'll read the code aloud and translate it in general terms.", "For a remote, I'll find the button you want in your photo and describe it by position: 'top right, just under the red one' — one press at a time, checking the result between presses.", "Codes about gas, electrics, or water under pressure stop here — those are a person's job, not a photo fix.")),
        HelperDef(92, "C", "What is this thing? (Show Nuri)", HelperMode.GUIDED, triggers = listOf("what is this thing", "what is this for", "identify this object"),
            steps = listOf("Tap 'Show Nuri' and take the photo. If I'm not sure from one side, I'll ask you to turn it over — writing on the back settles most mysteries.", "I'll name it and say what it's for in one sentence, and how sure I am. If I don't know, I'll say so cheerfully — some things need human eyes, and we can ask with the photo.", "For a plant, I may offer a likely name with my confidence stated — and the hard line follows: we never eat or brew anything we can't name for certain, and I can't tell you it's safe.")),
        HelperDef(93, "C", "Read this sign for me (Show Nuri)", HelperMode.GUIDED, triggers = listOf("read this sign", "sign out here", "price tag", "shelf label"),
            steps = listOf("From where you're safely standing — never step somewhere unsafe for a better photo — tap 'Show Nuri' and photo the sign.", "I'll read it, then give you only the part that matters now: the floor, the counter, the hours, the price — including the small per-ounce print when you're comparing.", "If a sign asks for payment by QR code to a stranger, the stop rule applies — we don't, and we ask a person instead.")),
        HelperDef(94, "C", "Which form is this — and where do I sign? (Show Nuri)", HelperMode.GUIDED, triggers = listOf("which form is this", "where do i sign", "show nuri form"),
            steps = listOf("Tap 'Show Nuri' and photo the top of the form first — naming it correctly is step zero. I'll also find the 'office use only' boxes; those aren't yours to fill.", "I'll explain each field in plain words before you write, and point to the signature line by landmarks: 'bottom of page two, the line with Signature under it.'", "I never fill in or sign anything for you. And legal, benefits, or court forms — or any field still unclear — stop here and go to a person, with your draft making their job fast.")),
        HelperDef(95, "C", "Read this card / handwritten note (Show Nuri)", HelperMode.GUIDED, triggers = listOf("who left this card", "read this note", "business card", "handwritten note"),
            steps = listOf("Tap 'Show Nuri' and photo it flat and lit — and check the back too; messages hide there. I'll read it aloud, fully, at your pace.", "Handwriting gets an honesty pass: if a word won't come clear, I'll say which one and what it looks like, never a silent guess.", "A card's details can become a contact with your OK — read back to confirm first. Family notes can go in your journal, so 'what did the note say?' is answerable later.")),
        HelperDef(96, "C", "Who is this in the photo? (Show Nuri)", HelperMode.GUIDED, triggers = listOf("who is this in the photo", "photo of a person", "who is this woman", "who is this man"),
